namespace DocProc.Infrastructure.Mail;

/// <summary>
/// The secret reference of a channel's credential (the mailbox password), generated by the server and never taken
/// from a request: <c>tenant/{tenantId}/channel/{channelId}</c>. The pollers read a channel's secret only under this
/// reference, so a row carrying another reference (legacy data, a client-chosen one) cannot hand a platform or another
/// tenant's secret to a tenant's IMAP server.
/// </summary>
public static class ChannelSecrets
{
    public static string Reference(Guid tenantId, Guid channelId) => $"tenant/{tenantId}/channel/{channelId}";
}
